#include <stdlib.h>
typedef struct{int*vals,*cnt,n,cap;}TwoSum;TwoSum* twoSumCreate(){TwoSum*t=calloc(1,sizeof(*t));t->cap=16;t->vals=malloc(t->cap*sizeof(int));t->cnt=malloc(t->cap*sizeof(int));return t;}void twoSumAdd(TwoSum*t,int x){for(int i=0;i<t->n;i++)if(t->vals[i]==x){t->cnt[i]++;return;}if(t->n==t->cap){t->cap*=2;t->vals=realloc(t->vals,t->cap*sizeof(int));t->cnt=realloc(t->cnt,t->cap*sizeof(int));}t->vals[t->n]=x;t->cnt[t->n++]=1;}bool twoSumFind(TwoSum*t,int v){for(int i=0;i<t->n;i++){int y=v-t->vals[i];for(int j=0;j<t->n;j++)if(t->vals[j]==y&&(i!=j||t->cnt[i]>1))return true;}return false;}void twoSumFree(TwoSum*t){free(t->vals);free(t->cnt);free(t);}
